import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { writeFile } from "node:fs/promises";

async function main() {
  let writerWsName = "writer-ws";
  let readerWsName = "reader-ws";

  // 1. Provision workspaces concurrently
  const [writerRes, readerRes] = await Promise.all([
    createWorkspace(writerWsName, { credentials: { role: "Editor" } }),
    createWorkspace(readerWsName, { credentials: { role: "ReadOnly" } })
  ]);

  if (writerRes.error) {
    throw new Error(`Failed to create writer workspace: ${writerRes.error.message}`);
  }
  if (readerRes.error) {
    throw new Error(`Failed to create reader workspace: ${readerRes.error.message}`);
  }

  const writerWorkspace = writerRes.data;
  const readerWorkspace = readerRes.data;

  // 2. Validate responses
  if (!writerWorkspace.bucket || !writerWorkspace.credentials?.accessKeyId || !writerWorkspace.credentials?.secretAccessKey) {
    throw new Error("Writer workspace is missing bucket or credentials");
  }
  if (!readerWorkspace.bucket || !readerWorkspace.credentials?.accessKeyId || !readerWorkspace.credentials?.secretAccessKey) {
    throw new Error("Reader workspace is missing bucket or credentials");
  }

  try {
    // 3. Create S3 Clients
    const writerClient = new S3Client({
      region: "REDACTED",
      endpoint: "REDACTED",
      credentials: {
        accessKeyId: writerWorkspace.credentials.accessKeyId,
        secretAccessKey: writerWorkspace.credentials.secretAccessKey,
      }
    });

    const readerClient = new S3Client({
      region: "REDACTED",
      endpoint: "REDACTED",
      credentials: {
        accessKeyId: readerWorkspace.credentials.accessKeyId,
        secretAccessKey: readerWorkspace.credentials.secretAccessKey,
      }
    });

    let writer_put_ok = false;
    let readonly_put_blocked = false;

    // 4. Perform role checks
    try {
      await writerClient.send(new PutObjectCommand({
        Bucket: writerWorkspace.bucket,
        Key: "note.txt",
        Body: "hello dual role"
      }));
      writer_put_ok = true;
    } catch (err: any) {
      console.error("Writer put failed:", err);
      writer_put_ok = false;
    }

    try {
      await readerClient.send(new PutObjectCommand({
        Bucket: readerWorkspace.bucket,
        Key: "note.txt",
        Body: "should be blocked"
      }));
      readonly_put_blocked = false;
    } catch (err: any) {
      const name = err.name || err.Code;
      const status = err.$metadata?.httpStatusCode;
      if (name === "AccessDenied" || name === "NotImplemented" || status === 403) {
        readonly_put_blocked = true;
      } else {
        console.error("Reader put failed with unexpected error:", err);
        readonly_put_blocked = false; // still failed, but maybe wrong reason
      }
    }

    // 5. Write JSON summary
    const result = {
      writer_bucket: writerWorkspace.bucket,
      reader_bucket: readerWorkspace.bucket,
      writer_put_ok,
      readonly_put_blocked
    };
    await writeFile("/home/user/dual-role/result.json", JSON.stringify(result, null, 2));

  } finally {
    // 6. Teardown workspaces
    await Promise.all([
      teardownWorkspace(writerWsName),
      teardownWorkspace(readerWsName)
    ]);
  }
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

